<script setup lang="ts">
import SettingsPanel from '../components/SettingsPanel.vue';
import { computed } from 'vue';
import UButton from '@nuxt/ui/components/Button.vue';
import UBadge from '@nuxt/ui/components/Badge.vue';
import UAlert from '@nuxt/ui/components/Alert.vue';
import UIcon from '@nuxt/ui/components/Icon.vue';
import { state, bytes, date } from '../store';
const env = computed(() => state.environment), worker = computed(() => state.status);
const runningSession = computed(() => state.sessions?.records.find(item => item.id === state.sessions?.execution.currentSessionId));
const memoryPercent = computed(() => env.value ? Math.round((1 - env.value.memory.hostFreeBytes / env.value.memory.hostTotalBytes) * 100) : 0);
const diskPercent = computed(() => env.value?.disk?.totalBytes ? Math.round((1 - env.value.disk.freeBytes / env.value.disk.totalBytes) * 100) : 0);
</script>
<template>
<section>
  <div class="page-heading"><div><h1 tabindex="-1">Worker dashboard</h1><p>See what is running, what needs attention and where this worker lives.</p></div><UButton color="neutral" variant="outline" to="/status" target="_blank" icon="i-lucide-braces">Status JSON</UButton></div>
  <div v-for="alert in state.monitoring?.alerts" :key="alert.code" class="notice"><UAlert :title="alert.message" :description="alert.remediation" color="warning" variant="soft" icon="i-lucide-triangle-alert" /></div>
  <div class="worker-map" role="group" aria-label="Worker environment and current connections"><div class="map-node"><UIcon name="i-lucide-network" /><strong>Orchestrator</strong><span>{{ worker?.lastContact ? 'Last contact ' + date(worker.lastContact) : worker?.state === 'standalone' ? 'Optional · not connected' : 'No contact recorded' }}</span></div><div class="map-link" aria-hidden="true"></div><div class="map-node current"><UIcon name="i-lucide-cpu" /><strong>{{ worker?.project ?? 'This worker' }}</strong><UBadge :color="['idle', 'executing', 'standalone'].includes(worker?.state ?? '') ? 'primary' : 'warning'" variant="subtle">{{ worker?.state ?? 'Connecting' }}</UBadge></div><div class="map-link" aria-hidden="true"></div><div class="map-node"><UIcon name="i-lucide-hard-drive" /><strong>Local journal</strong><span>{{ worker?.outbox ? worker.outbox.pending + ' snapshots awaiting delivery' : 'Delivery state unavailable' }}</span></div></div>
  <section class="monitor-section" aria-label="Worker activity overview"><div class="section-heading"><h2>Work in progress</h2><UButton to="/history" variant="outline" color="neutral">Open taskboard</UButton></div>
    <ol class="activity-flow"><li><strong>{{ state.sessions?.execution.queued ?? '—' }}</strong><span>Tasks waiting</span></li><li><strong>{{ state.sessions ? state.sessions.execution.currentSessionId ? 1 : 0 : '—' }}</strong><span>Task running</span></li><li><strong>{{ state.board ? state.board.tasks.filter(task => task.status === 'review' && !task.archived).length : '—' }}</strong><span>Ready for review</span></li></ol>
    <dl class="facts"><div><dt>Task sessions</dt><dd>{{ state.sessions ? state.sessions.records.filter(session => !session.archived).length + ' saved · one execution at a time' : 'Unlock to inspect' }}</dd></div><div><dt>Remote assignments waiting</dt><dd>{{ worker?.queuedTasks?.length ?? 0 }}</dd></div><div><dt>Local queue</dt><dd>{{ state.settings ? state.settings.board.paused ? 'Paused' : 'Accepting work' : 'Unlock to inspect' }}</dd></div></dl>
  </section>
  <details class="monitor-section"><summary>Provider connections &amp; orchestrator enrollment</summary><SettingsPanel /></details>
  <section class="monitor-section"><div class="section-heading"><h2>Worker execution</h2><span class="muted">One task at a time</span></div><div class="slot" :class="{ occupied: !!state.sessions?.execution.currentSessionId }"><UIcon name="i-lucide-cpu" /><div><strong>{{ state.sessions ? runningSession ? 'Running · ' + runningSession.title : state.sessions.execution.currentSessionId ? 'Task running' : 'Ready for the next task' : 'Unlock to inspect execution' }}</strong><span>{{ runningSession?.provider ?? 'Chat, file tasks and orchestrator assignments share this worker.' }}</span></div></div><p class="page-note">Queued work starts when the current task finishes. Add more workers to execute tasks in parallel.</p></section>
  <div class="monitor-columns">
    <section class="monitor-section"><h2>Worker health</h2><dl class="facts"><div><dt>Worker ID</dt><dd>{{ worker?.workerId ?? 'Not registered' }}</dd></div><div><dt>Execution mode</dt><dd>{{ worker?.mode === 'mock' ? 'Simulation' : worker?.mode === 'cli' ? 'Live Codex' : 'Unavailable' }}</dd></div><div><dt>Completed simulations · this process</dt><dd>{{ worker?.completedSimulations ?? '—' }}</dd></div><div><dt>Change sets for review · this process</dt><dd>{{ worker?.completedReviews ?? '—' }}</dd></div><div><dt>Heartbeat errors · this process</dt><dd>{{ worker?.heartbeatErrors ?? '—' }}</dd></div><div><dt>Latest reported error</dt><dd>{{ worker?.lastError ?? 'None recorded' }}</dd></div></dl></section>
    <section class="monitor-section"><h2>Profiles &amp; model</h2><ul class="profile-list"><li v-for="profile in worker?.profiles" :key="profile.id"><UIcon name="i-lucide-box" /><div><strong>{{ profile.id }}</strong><span>{{ profile.provider }} · {{ profile.mode === 'mock' ? 'Simulated' : 'Live CLI' }}</span></div></li></ul><p>{{ env?.chat.configured ? 'Selected task provider: ' + env.chat.provider + '.' : 'Chat model: ' + (state.unlocked ? 'not configured.' : 'unlock to inspect.') }}</p><p class="page-note">A configured profile does not verify provider login, quota or remaining subscription. Provider usage and cost are unavailable.</p></section>
  </div>
  <template v-if="env">
    <section class="monitor-section"><h2>Environment resources</h2><p class="page-note">Live samples from the worker host. Process RSS and heap describe this Node worker, excluding its model subprocess.</p><div class="resources"><div><div class="measure-label"><strong>Host memory in use</strong><span>{{ memoryPercent }}%</span></div><meter :value="memoryPercent" min="0" max="100" aria-label="Host memory in use" /><p>{{ bytes(env.memory.hostFreeBytes) }} free of {{ bytes(env.memory.hostTotalBytes) }}</p></div><div><div class="measure-label"><strong>State-volume space used</strong><span>{{ env.disk ? diskPercent + '%' : 'Unavailable' }}</span></div><meter v-if="env.disk" :value="diskPercent" min="0" max="100" aria-label="State volume used" /><p>{{ env.disk ? bytes(env.disk.freeBytes) + ' available of ' + bytes(env.disk.totalBytes) : 'The operating system did not provide a measurement.' }}</p></div></div><dl class="facts resource-facts"><div><dt>Worker-process RSS</dt><dd>{{ bytes(env.memory.processRssBytes) }}</dd></div><div><dt>Worker heap used / allocated</dt><dd>{{ bytes(env.memory.heapUsedBytes) }} / {{ bytes(env.memory.heapTotalBytes) }}</dd></div><div><dt>Host load · 1 / 5 / 15 min</dt><dd>{{ env.hostLoad ? env.hostLoad.map(value => value.toFixed(2)).join(' / ') : 'Unavailable on this platform' }}</dd></div><div><dt>Available logical CPUs</dt><dd>{{ env.logicalCpus }}</dd></div></dl></section>
    <div class="monitor-columns"><section class="monitor-section"><h2>Runtime</h2><dl class="facts"><div><dt>Host</dt><dd>{{ env.hostname }}</dd></div><div><dt>Operating system</dt><dd>{{ env.platform }} {{ env.osRelease }} · {{ env.architecture }}</dd></div><div><dt>Node.js / process ID</dt><dd>{{ env.nodeVersion }} / {{ env.pid }}</dd></div><div><dt>Uptime</dt><dd>{{ Math.floor(env.uptimeSeconds / 60) }} min {{ Math.floor(env.uptimeSeconds % 60) }} s</dd></div></dl></section><section class="monitor-section"><h2>Connection &amp; storage</h2><dl class="facts"><div><dt>Orchestrator</dt><dd>{{ env.orchestratorUrl ?? 'Standalone' }}</dd></div><div><dt>State directory</dt><dd>{{ env.stateDirectory }}</dd></div><div><dt>Project directory</dt><dd>{{ env.projectDirectory ?? 'Not configured' }}</dd></div><div><dt>Poll interval / task timeout</dt><dd>{{ env.pollMs }} ms / {{ env.taskTimeoutMs / 1000 }} s</dd></div><div><dt>Retained acknowledged pairs</dt><dd>{{ env.retainedPairs }}</dd></div></dl></section></div>
  </template>
  <div v-else class="environment-locked"><UIcon name="i-lucide-lock-keyhole" /><p>Unlock this worker to see its host resources, runtime and storage configuration.</p></div>
  <details class="monitor-section"><summary>Configuration &amp; evidence identifiers</summary><dl class="facts"><div><dt>Configuration hash</dt><dd>{{ worker?.configurationHash ?? 'Unavailable' }}</dd></div><div><dt>Latest snapshot</dt><dd>{{ worker?.lastSnapshot ?? 'None recorded in this process' }}</dd></div><div><dt>Status recorded</dt><dd>{{ date(worker?.updatedAt) }}</dd></div></dl></details>
</section>
</template>
